const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const n = parseInt(line.trim());
    let count = 0;

    for (let a = 1; a <= n; a++) {
        for (let b = a; b <= n; b++) {
            const c = a ^ b;
            if (c < b) continue;
            if (c > n) continue;
            // Check triangle inequality: a + b > c (since a <= b <= c, other inequalities are satisfied)
            if (a + b > c) {
                count++;
            }
        }
    }

    console.log(count);
});
