const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let line = '';
rl.on('line', (input) => {
    line = input.trim();
    rl.close();
});

rl.on('close', () => {
    const n = parseInt(line, 10);

    // Count triples (a, b, c) such that:
    // 1 <= a <= b <= c <= n
    // a ^ b ^ c === 0
    // a + b > c (non-degenerate triangle condition, since a <= b <= c, we only need a + b > c)

    let count = 0;

    for (let a = 1; a <= n; a++) {
        for (let b = a; b <= n; b++) {
            const c = a ^ b;
            // We need c >= b (since a <= b <= c)
            if (c < b) continue;
            // We need c <= n
            if (c > n) continue;
            // Triangle inequality: a + b > c
            if (a + b > c) {
                count++;
            }
        }
    }

    console.log(count);
});
