const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const n = parseInt(line.trim());

    // Count triples (a, b, c) such that 1 <= a <= b <= c <= n
    // a ^ b ^ c === 0
    // and they form a non-degenerate triangle: a + b > c (since a <= b <= c, this is the only condition needed)

    let count = 0;

    for (let a = 1; a <= n; a++) {
        for (let b = a; b <= n; b++) {
            // c must satisfy a ^ b ^ c === 0 => c = a ^ b
            const c = a ^ b;

            // Check if c is in valid range
            if (c < b) continue; // we need b <= c
            if (c > n) continue;

            // Check triangle inequality: a + b > c
            // Since a <= b <= c, the other two inequalities (a + c > b and b + c > a) are automatically satisfied
            if (a + b > c) {
                count++;
            }
        }
    }

    console.log(count);
});
